/**
 * Conductor PWA - Built-in Robot Voice
 *
 * Synthesizes short spoken lines offline with meSpeak (eSpeak compiled to JS) and
 * registers them as decoded AudioBuffers under the reserved resource-pack id
 * '__robot', so pack playback and the offline audio bake use them unchanged.
 *
 * The engine ships gzipped + base64 in window.ROBOT_VOICE_GZ_B64 (generated by
 * scripts/build-robot-voice.js into docs/lib/robot-voice.js) and is only inflated
 * and evaluated on the first load() - never at page load. The global string is
 * left intact because "share this app" re-serialises the page.
 *
 * Pure of DOM / speechSynthesis: all audio plumbing arrives through createRobotVoice opts.
 *
 * Requires: window.ROBOT_VOICE_GZ_B64 (lib/robot-voice.js), pako (lib/pako.min.js)
 */

/**
 * @param {Object} opts
 * @param {function(): (AudioContext|null)} opts.getAudioContext
 * @param {function(string, AudioBuffer): void} opts.registerBuffer - cache key is packId + ':' + cueId
 * @param {function(string): boolean} opts.hasBuffer
 */
function createRobotVoice(opts) {
    /**
     * Per-style eSpeak settings (voice is always 'en/en-us', amplitude 100). Tuned for
     * intelligibility, not naturalness: triggers are the moment-of-action word so they
     * run fast with no word gap; notices and clips are read a little slower with a gap.
     */
    const ROBOT_STYLES = Object.freeze({
        trigger: Object.freeze({ speed: 175, wordgap: 0, pitch: 50 }),
        notice: Object.freeze({ speed: 160, wordgap: 1, pitch: 50 }),
        clip: Object.freeze({ speed: 160, wordgap: 1, pitch: 50 }),
    });

    const ROBOT_PACK_ID = '__robot';
    const ROBOT_VOICE_NAME = 'en/en-us';
    const ROBOT_SILENCE_THRESHOLD = 0.004;
    const ROBOT_TRIM_PAD_SEC = 0.015;

    function _robotNormalise(text) {
        return String(text).trim().replace(/\s+/g, ' ');
    }

    function _robotYield() {
        return new Promise(r => setTimeout(r, 0));
    }

    function _robotCheckStyle(style) {
        if (!Object.prototype.hasOwnProperty.call(ROBOT_STYLES, style)) {
            throw new TypeError('robot voice: unknown style ' + style);
        }
    }

    /**
     * Parse a RIFF/WAVE ArrayBuffer (16-bit PCM) into mono Float32 samples.
     * Tolerates bogus data-chunk sizes (0 / 0xFFFFFFFF) by using the remaining bytes.
     * @returns {{samples: Float32Array, sampleRate: number}|null}
     */
    function _robotParseWav(ab) {
        if (!ab || ab.byteLength < 12) return null;
        const dv = new DataView(ab);
        const tag = (o) => String.fromCharCode(dv.getUint8(o), dv.getUint8(o + 1), dv.getUint8(o + 2), dv.getUint8(o + 3));
        if (tag(0) !== 'RIFF' || tag(8) !== 'WAVE') return null;

        let channels = 0, sampleRate = 0, dataStart = -1, dataLen = 0;
        let pos = 12;
        while (pos + 8 <= ab.byteLength) {
            const id = tag(pos);
            const size = dv.getUint32(pos + 4, true);
            const body = pos + 8;
            if (id === 'fmt ' && body + 16 <= ab.byteLength) {
                if (dv.getUint16(body, true) !== 1 || dv.getUint16(body + 14, true) !== 16) return null;
                channels = dv.getUint16(body + 2, true);
                sampleRate = dv.getUint32(body + 4, true);
            } else if (id === 'data') {
                const remaining = ab.byteLength - body;
                dataStart = body;
                dataLen = (size === 0 || size > remaining) ? remaining : size;
                break;
            }
            pos = body + size + (size & 1);
        }
        if (!channels || !sampleRate || dataStart < 0) return null;

        const frames = Math.floor(dataLen / (2 * channels));
        const samples = new Float32Array(frames);
        for (let i = 0; i < frames; i++) {
            let sum = 0;
            for (let c = 0; c < channels; c++) sum += dv.getInt16(dataStart + (i * channels + c) * 2, true);
            samples[i] = sum / channels / 32768;
        }
        return { samples, sampleRate };
    }

    // The npm build of meSpeak never calls its own recovery for eSpeak's
    // virtual-file bug, so an engine instance breaks for good after ~80
    // syntheses (measured: 79 ok, then every call fails and memory balloons).
    // A fresh instance is cheap (~0.1-0.3 s), so swap one in well before that.
    const ROBOT_CALLS_PER_ENGINE = 60;

    let engine = null;
    let engineCalls = 0;
    let loadPromise = null;
    let loadError = null;
    let loadMs = null;

    function isAvailable() {
        return typeof window.ROBOT_VOICE_GZ_B64 === 'string' && window.ROBOT_VOICE_GZ_B64.length > 0
            && !!window.pako && typeof pako.inflate === 'function';
    }

    function load() {
        if (loadPromise) return loadPromise;
        loadPromise = (async () => {
            if (!isAvailable()) throw new Error('robot voice not bundled');
            await _robotYield(); // let a caller's "loading..." UI paint before the heavy work
            const t0 = Date.now();
            freshEngine();
            loadMs = Date.now() - t0;
            loadError = null;
        })().catch((e) => {
            loadError = (e && e.message) || String(e);
            loadPromise = null; // allow a later retry
            console.warn('Robot voice failed to load:', loadError);
            throw e;
        });
        return loadPromise;
    }

    /** Inflate + evaluate a new engine instance (sync) and make it current. */
    function freshEngine() {
        engine = null; // drop the old instance (and its ~50 MB heap) first
        const bin = atob(window.ROBOT_VOICE_GZ_B64);
        const bytes = new Uint8Array(bin.length);
        for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
        const eng = new Function(pako.inflate(bytes, { to: 'string' }))();
        if (!eng || typeof eng.speak !== 'function' || !eng.isConfigLoaded() || !eng.isVoiceLoaded(ROBOT_VOICE_NAME)) {
            throw new Error('robot voice engine did not initialise');
        }
        engine = eng;
        engineCalls = 0;
    }

    /** One engine call → WAV ArrayBuffer or null, recycling the instance on schedule. */
    function speakRaw(text, style) {
        // Lazily (re)build: on schedule, or after a rebuild that threw left
        // no engine. A throw here propagates to the caller's per-line catch,
        // and the next line tries again — one bad rebuild can't kill the voice.
        if (!engine || engineCalls >= ROBOT_CALLS_PER_ENGINE) freshEngine();
        engineCalls++;
        try {
            const ab = engine.speak(text, Object.assign(
                { rawdata: 'arraybuffer', voice: ROBOT_VOICE_NAME, amplitude: 100 }, ROBOT_STYLES[style]));
            return (ab && ab.byteLength) ? ab : null;
        } catch (e) {
            return null;
        }
    }

    function cueId(style, text) {
        _robotCheckStyle(style);
        return style + ':' + _robotNormalise(text);
    }

    function key(style, text) {
        return ROBOT_PACK_ID + ':' + cueId(style, text);
    }

    /** Synthesize one line to a trimmed mono AudioBuffer, or null on failure/silence. */
    function synthToAudioBuffer(text, style, ctx) {
        if (!loadMs && !engine) throw new Error('robot voice not loaded');
        _robotCheckStyle(style);
        const line = _robotNormalise(text);
        let ab = speakRaw(line, style);
        if (!ab) { freshEngine(); ab = speakRaw(line, style); } // broken instance: one retry on a fresh one
        if (!ab) return null;
        const wav = _robotParseWav(ab);
        if (!wav) return null;

        // Trim near-silence at both ends (head matters: a trigger must land on the downbeat).
        const { samples, sampleRate } = wav;
        let first = 0, last = samples.length - 1;
        while (first <= last && Math.abs(samples[first]) < ROBOT_SILENCE_THRESHOLD) first++;
        while (last >= first && Math.abs(samples[last]) < ROBOT_SILENCE_THRESHOLD) last--;
        if (first > last) return null;
        const pad = Math.round(ROBOT_TRIM_PAD_SEC * sampleRate);
        const trimmed = samples.subarray(Math.max(0, first - pad), Math.min(samples.length, last + 1 + pad));

        const buf = ctx.createBuffer(1, trimmed.length, sampleRate);
        buf.getChannelData(0).set(trimmed);
        return buf;
    }

    /**
     * Synthesize and register every unique line not already cached.
     * Never rejects: failures come back as {ok:false, error}.
     * @param {Array<{style:string, text:string}>} lines
     * @returns {Promise<{ok:boolean, total:number, synthesized:number, cached:number, failed:number, ms:number, error?:string}>}
     */
    async function prepare(lines) {
        const t0 = Date.now();
        const unique = new Map();
        for (const l of lines || []) {
            if (!_robotNormalise(l.text)) continue;
            unique.set(key(l.style, l.text), l);
        }
        const result = { ok: false, total: unique.size, synthesized: 0, cached: 0, failed: 0, ms: 0 };
        const finish = (extra) => Object.assign(result, { ms: Date.now() - t0 }, extra);

        try {
            await load();
        } catch (e) {
            return finish({ error: (e && e.message) || String(e) });
        }
        const ctx = opts.getAudioContext();
        if (!ctx) return finish({ error: 'no audio context' });

        for (const [k, l] of unique) {
            if (opts.hasBuffer(k)) { result.cached++; continue; }
            try {
                const buf = synthToAudioBuffer(l.text, l.style, ctx);
                if (buf) { opts.registerBuffer(k, buf); result.synthesized++; } else result.failed++;
            } catch (e) {
                console.warn('Robot voice synth failed for "' + l.text + '":', e);
                result.failed++;
            }
            await _robotYield();
        }
        // Release the engine (~50 MB of emulated memory) between events; the
        // next prepare() rebuilds it in a fraction of a second.
        engine = null;
        return finish({ ok: result.failed === 0 });
    }

    return {
        PACK_ID: ROBOT_PACK_ID,
        isAvailable,
        load,
        isLoaded: () => loadMs !== null, // loaded successfully at least once (engine itself is released after prepare)
        getError: () => loadError,
        getLoadMs: () => loadMs,
        cueId,
        key,
        synthToAudioBuffer,
        prepare,
    };
}
